```sql
CREATE TABLE Schedule (
    id INT AUTO_INCREMENT PRIMARY KEY,
    event_id INT NOT NULL,
    schedule_time TIME NOT NULL,
    recurrence_id INT NOT NULL,
    FOREIGN KEY (event_id) REFERENCES Events(id),
